import static org.junit.Assert.*;
import org.junit.Test;
import org.mockito.Mockito;
import java.util.*;
import app.DBApp;
import exceptions.DBAppException;
import sql.SQLTerm;

public class DBAppTest {

  @Test
  public void createTableNormalFlowTest() throws DBAppException {
    DBApp dbApp = new DBApp();
    Hashtable<String, String> htblColNameType = new Hashtable<String, String>() {{
        put("id", "int");
        put("name", "string");
    }};
    Hashtable<String, String> htblColNameMin = new Hashtable<String, String>() {{
        put("id", "0");
        put("name", "a");
    }};
    Hashtable<String, String> htblColNameMax = new Hashtable<String, String>() {{
        put("id", "100");
        put("name", "z");
    }};
    dbApp.createTable("student", "id", htblColNameType, htblColNameMin, htblColNameMax);
    HashSet<String> myTables = dbApp.getMyTables();
    assertTrue(myTables.contains("student"));
  }

  @Test(expected=DBAppException.class)
  public void insertIntoTableExceptionTest() throws DBAppException {
    DBApp dbApp = new DBApp();
    Hashtable<String, Object> htblColNameValue = new Hashtable<String, Object>() {{
        put("id", "101"); //value exceeding the set maximum
        put("name", "ab");
    }};
    dbApp.insertIntoTable("student", htblColNameValue);
  }

  @Test
  public void updateTableNormalFlowTest() throws DBAppException {
    DBApp dbApp = new DBApp();
    Hashtable<String, Object> htblColNameValue = new Hashtable<String, Object>() {{
        put("name", "not_anymore");
    }};
    dbApp.updateTable("student", "1", htblColNameValue); //assuming that a row with id = 1 exists
    Iterator result = dbApp.selectFromTable(null, null); //dummy operation to get all data
    while(result.hasNext()) {
        assertNotEquals(((Hashtable) result.next()).get("name"), "ab");
    }
  }

  @Test
  public void getReaderNotNullTest() {
    DBApp dbApp = new DBApp();
    assertNotNull(dbApp.getReader());
  }

  @Test
  public void getWriterNotNullTest() {
    DBApp dbApp = new DBApp();
    assertNotNull(dbApp.getWriter());
  }
}
